function OverseaClubBossRankMemberNode:RefreshShow(type,data)
    self.type = type
    self.data = data
    KTool.SetActive(self.InClub.gameObject,self.type == ClubUtils.BossRankType.ClubMember)
    KTool.SetActive(self.InServer.gameObject,self.type == ClubUtils.BossRankType.Personnel)
    KTool.SetActive(self.FontStyleButton.gameObject,self.type == ClubUtils.BossRankType.Personnel)
    if self.type == ClubUtils.BossRankType.ClubMember then
        self:FillClubInfo()
    elseif self.type == ClubUtils.BossRankType.Personnel then
        self:FillServerInfo()
    end
    self:FillCommonInfo()
end

function OverseaClubBossRankMemberNode:ShowBtnLast(flag)
    CfUtils.SetActive(self.FontStyleButton.gameObject,flag and self.type == ClubUtils.BossRankType.Personnel)
end

function OverseaClubBossRankMemberNode:FillServerInfo()
    self:SetTitleShow(self.isCurrent)
    local isInRank = self.data.myRank.ranking > 0
    KTool.SetActive(self.ServerLayout.gameObject,isInRank)
    KTool.SetActive(self.ServerEmpty.gameObject,not isInRank)
    CfUtils.FillText(self.ServerRank.gameObject,self.data.myRank.ranking)
    CfUtils.FillText(self.DamageNum,self.data.myRank.score)
end

function OverseaClubBossRankMemberNode:SetTitleShow(isCurrent)
    local status = isCurrent and 2 or 1
    CfUtils.SetUISwitchText(self.TitleDesc,status)
    CfUtils.SetUISwitchText(self.BtnDes,status)
end

function OverseaClubBossRankMemberNode:FillClubInfo()
    local clubHomeDojo = ClubUtils.GetClubComp():GetHomeDojo()
    local clubHeadVo = ClubUtils.GetClubHeadVo(clubHomeDojo.avatar)
    CfUtils.FillImage(self.ClubIcon.gameObject,clubHeadVo.photoPath)
    CfUtils.FillText(self.ClubName,clubHomeDojo.name)

    local rankInfo = self:GetMyRankInfo()
    if not isNull(rankInfo) then
        KTool.SetActive(self.ClubLayout.gameObject,true)
        KTool.SetActive(self.ClubEmpty.gameObject,false)
        CfUtils.FillText(self.ClubRank.gameObject,rankInfo.ranking)
        CfUtils.FillText(self.DamageNum,rankInfo.score)
    else
        KTool.SetActive(self.ClubLayout.gameObject,false)
        KTool.SetActive(self.ClubEmpty.gameObject,true)
        CfUtils.FillText(self.DamageNum,0)
    end
end

function OverseaClubBossRankMemberNode:GetMyRankInfo()
    local myRank
    local playerDojo = playerComponent.playerDojo
    for i, v in pairs(self.data.rankInfo) do
        if v.playerId == checkNumber(playerDojo:PlayerId()) then
            myRank = v
        end
    end
    return myRank
end

function OverseaClubBossRankMemberNode:FillCommonInfo()
    local playerDojo = playerComponent.playerDojo
    if not isNull(playerDojo) then
        CfUtils.FillText(self.PlayerName,playerDojo.playerName)
        CfUtils.FillText(self.PlayerLevel,table.concat({"Lv.",playerDojo.level}))
        ---@type CommonPlayerHeadNode
        local env = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, CommonPlayerHeadNode)
        if env then
            env:FreshAvatarFrame(playerDojo.playerAvatar, playerDojo.playerAvatarFrame)
        end
    end
    self:RefreshListView()
end

function OverseaClubBossRankMemberNode:RefreshListView()
    if self.MemberRankSv then
        local count = table.count(self.data.rankInfo)
        if not self.MemberRankSv.IsListViewInit then
            self.MemberRankSv:InitListView(count, Bind(self, self.OnRefreshCellIndex))
--[[            self.MemberRankSv:UpdateDisplayItemCount("Cell")
            if not self.aniTypeMap[self.type] then
                self.aniTypeMap[self.type] = true
            end]]
        else
            GameUtils.ReloadData(self.MemberRankSv, count)
