                self.MemberRankSv.DisplayItemNumber = 0
                self.aniTypeMap[self.type] = true
            end]]
        end
        self.MemberRankSv:MovePanelToItemIndex(0,0)
    end
end

function OverseaClubBossRankMemberNode:OnRefreshCellIndex(listView,index)
    if index < 0 or index >= #self.data.rankInfo then
        return
    end
    local cell = listView:NewListViewItem("Cell")
    local tableCellEnv = CfUtils.GetLuaScr(cell, CellPath)
    if not isNull(tableCellEnv) then
        tableCellEnv:RefreshShow(self.data.rankInfo[index + 1])
--[[        if listView.DisplayItemNumber < listView.DisplayItemCount then
            tableCellEnv:PlayDelayAnimByShow(listView.DisplayItemNumber)
            listView.DisplayItemNumber = listView.DisplayItemNumber + 1
        else
            tableCellEnv:PlayAnimByIdle()
        end]]
    end
    return cell
end

function OverseaClubBossRankMemberNode:OnFontStyleButtonClick()
    self.isCurrent = not self.isCurrent
    if self.callBack then
        self.callBack(self.isCurrent)
    end
end

